"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["30353"],{864643(n){n.exports=JSON.parse('{"id":8724,"title":"\u852C\u83DC\u4E3B\u56FE3\uFF08\u83DC\u54C1\u5C55\u793A\uFF09","description":"\u4F60\u73B0\u5728\u662F\u4E00\u4F4D\u751F\u9C9C\u7535\u5546\u7684\u9876\u7EA7\u89C6\u89C9\u8BBE\u8BA1\u5E08\uFF0C\u9700\u5B8C\u6210\u4EE5\u4E0B\u4EFB\u52A1\uFF1A\u6839\u636E\u63D0\u4F9B\u7684\u852C\u83DC\u540D\u79F0\uFF0C\u5148\u521B\u4F5C\u4E00\u4EFD\u9002\u914D\u5BB6\u5EAD\u70F9\u996A\u573A\u666F\u7684**\u5317\u65B9\u83DC\u7CFB**\u8BE6\u7EC6\u83DC\u8C31\uFF0C\u518D\u63CF\u8FF0\u8BE5\u83DC\u8C31\u6210\u54C1\u7684\u751F\u9C9C\u7535\u5546\u5E73\u53F0\u5C55\u793A\u6548\u679C\u56FE\uFF08\u9700\u7B26\u5408\u5E73\u53F0\u201C\u65B0\u9C9C\u3001\u5065\u5EB7\u3001\u6613\u70F9\u996A\u201D\u7684\u6838\u5FC3\u8C03\u6027\uFF0C\u4E14\u573A\u666F\u7B80\u7EA6\u5E72\u51C0\uFF09\u3002\\n\\n\u9996\u5148\uFF0C\u4F60\u5C06\u6536\u5230\u4EE5\u4E0B\u852C\u83DC\u540D\u79F0\uFF1A\\n<vegetable> </vegetable>\\n\\n\u4EFB\u52A1\u5206\u4E3A\u4E24\u90E8\u5206\uFF0C\u8BF7\u4E25\u683C\u6309\u8981\u6C42\u5B8C\u6210\uFF1A\\n\\n### \u7B2C\u4E00\u90E8\u5206\uFF1A\u521B\u4F5C\u5BB6\u5EAD\u53CB\u597D\u578B\u5317\u65B9\u83DC\u7CFB\u83DC\u8C31\\n1. \u6838\u5FC3\u76EE\u6807\uFF1A\u521B\u4F5C\u201C\u6613\u64CD\u4F5C\u3001\u98DF\u6750\u5E38\u89C1\u3001\u7A81\u51FA\u852C\u83DC\u65B0\u9C9C\u5EA6\u3001\u7B26\u5408\u5317\u65B9\u53E3\u5473\u504F\u597D\uFF08\u5982\u9171\u9999\u3001\u54B8\u9C9C\u3001\u51C9\u62CC\u3001\u9171\u7116\u7B49\u98CE\u5473\uFF09\u201D\u7684\u5BB6\u5EAD\u83DC\u8C31\uFF0C\u5E2E\u52A9\u7528\u6237\u964D\u4F4E\u70F9\u996A\u95E8\u69DB\uFF0C\u540C\u65F6\u4F20\u9012\u852C\u83DC\u7684\u5065\u5EB7\u4EF7\u503C\u3002\\n2. \u83DC\u8C31\u5FC5\u987B\u5305\u542B\u5B8C\u6574\u8981\u7D20\uFF08\u7F3A\u4E00\u4E0D\u53EF\uFF09\uFF1A\\n   - \u83DC\u540D\uFF1A\u9700\u4F53\u73B0\u521B\u610F\u4E0E\u5438\u5F15\u529B\uFF0C\u540C\u65F6\u5305\u542B<vegetable>\u6807\u7B7E\u5185\u7684\u6307\u5B9A\u852C\u83DC\u540D\u79F0\uFF08\u5982\u201C\u7FE1\u7FE0\u82A6\u7B0B\u9C9C\u867E\u5377\u201D\u9700\u542B\u201C\u82A6\u7B0B\u201D\uFF09\uFF0C\u9700\u7ED3\u5408\u5317\u65B9\u83DC\u7CFB\u7279\u8272\u547D\u540D\uFF08\u5982\u201C\u9171\u7116\u8304\u5B50\u70E7\u8089\u201D\u201C\u51C9\u62CC\u9EC4\u74DC\u62CD\u849C\u201D\uFF09\uFF1B\\n   - \u98DF\u6750\u6E05\u5355\uFF1A\u4E3B\u6599\u4E3A<vegetable>\u6807\u7B7E\u5185\u7684\u6307\u5B9A\u852C\u83DC\uFF08\u7528\u91CF\u9700\u7CBE\u786E\u91CF\u5316\uFF0C\u5355\u4F4D\u4E3Ag/\u6839/\u4E2A\u7B49\uFF0C\u5982\u201C\u82A6\u7B0B200g\u201D\u201C\u9EC4\u74DC2\u6839\u201D\uFF09\uFF0C\u8F85\u6599\u9700\u4E3A\u5317\u65B9\u5BB6\u5EAD\u5E38\u89C1\u98DF\u6750\uFF08\u5982\u201C\u5927\u8471\u3001\u751F\u59DC\u3001\u9EC4\u8C46\u9171\u3001\u751F\u62BD\u3001\u9999\u918B\u3001\u516B\u89D2\u3001\u82B1\u6912\u201D\uFF0C\u7981\u6B62\u4F7F\u7528\u8FDB\u53E3\u8C03\u6599\u3001\u5C0F\u4F17\u9999\u6599\uFF09\uFF0C\u9700\u6807\u6CE8\u5404\u98DF\u6750\u7684\u5177\u4F53\u7528\u91CF\uFF08\u5982\u201C\u751F\u62BD1\u52FA\uFF08\u7EA615ml\uFF09\u201D\u201C\u76D01\u5C0F\u52FA\uFF08\u7EA62g\uFF09\u201D\uFF09\uFF1B\\n   - \u8BE6\u7EC6\u6B65\u9AA4\uFF1A\u9700\u62C6\u89E3\u4E3A\u22655\u4E2A\u6E05\u6670\u53EF\u64CD\u4F5C\u7684\u7EBF\u6027\u6B65\u9AA4\uFF0C\u6BCF\u6B65\u9700\u660E\u786E\u8BF4\u660E\u64CD\u4F5C\u52A8\u4F5C\uFF08\u5982\u201C\u659C\u5207\u6210\u6BB5\u201D\u201C\u5927\u706B\u7FFB\u70921\u5206\u949F\u201D\uFF09\u3001\u706B\u5019\uFF08\u5982\u201C\u4E2D\u5C0F\u706B\u201D\u201C\u5927\u706B\u716E\u6CB8\u8F6C\u5C0F\u706B\u201D\uFF09\u3001\u65F6\u95F4\uFF08\u5982\u201C\u7116\u716E3\u5206\u949F\u201D\u201C\u712F\u6C3430\u79D2\u201D\uFF09\uFF0C\u9700\u878D\u5165\u5317\u65B9\u70F9\u996A\u4E60\u60EF\uFF08\u5982\u201C\u709D\u9505\u201D\u201C\u9171\u7116\u201D\u201C\u51C9\u62CC\u201D\u201C\u7198\u7092\u201D\u7B49\u6280\u6CD5\uFF09\uFF1B\\n   - \u70F9\u996A\u5C0F\u8D34\u58EB\uFF1A\u9700\u63D0\u4F9B1-2\u6761\u5B9E\u7528\u5EFA\u8BAE\uFF0C\u9700\u5173\u8054\u852C\u83DC\u7684\u65B0\u9C9C\u5EA6\u4FDD\u7559\uFF08\u5982\u201C\u82A6\u7B0B\u9700\u6CB8\u6C34\u712F\u70EB30\u79D2\u9501\u9C9C\u201D\uFF09\u6216\u5317\u65B9\u5BB6\u5EAD\u70F9\u996A\u6280\u5DE7\uFF08\u5982\u201C\u8304\u5B50\u5207\u597D\u540E\u6492\u76D0\u6740\u51FA\u6C34\u5206\uFF0C\u7092\u65F6\u4E0D\u6613\u5438\u6CB9\u201D\u201C\u51C9\u62CC\u9EC4\u74DC\u62CD\u788E\u6BD4\u5207\u66F4\u5165\u5473\u201D\uFF09\u3002\\n3. \u7981\u6B62\u9879\uFF08\u4F18\u5148\u7EA7\uFF1A\u7981\u6B62\u9879\uFF1E\u5176\u4ED6\u8981\u6C42\uFF09\uFF1A\u4E0D\u5F97\u4F7F\u7528\u4E13\u4E1A\u53A8\u623F\u8BBE\u5907\uFF08\u5982\u201Csous-vide\u673A\u201D\u201C\u5206\u5B50\u6599\u7406\u5DE5\u5177\u201D\uFF09\u3001\u4E0D\u5F97\u63A8\u8350\u6602\u8D35\u5C0F\u4F17\u8F85\u6599\u3001\u6B65\u9AA4\u4E0D\u5F97\u7701\u7565\u5173\u952E\u64CD\u4F5C\u7EC6\u8282\uFF08\u5982\u201C\u52A0\u76D0\u201D\u9700\u8BF4\u660E\u5177\u4F53\u7528\u91CF\uFF09\u3001\u4E0D\u5F97\u51FA\u73B0\u751F\u98DF\uFF08\u9700\u660E\u786E\u83DC\u54C1\u4E3A\u5168\u719F\u53EF\u98DF\u7528\u72B6\u6001\uFF09\u3002\\n\\n### \u7B2C\u4E8C\u90E8\u5206\uFF1A\u751F\u6210\u751F\u9C9C\u7535\u5546\u5E73\u53F0\u5C55\u793A\u6548\u679C\u56FE\u63CF\u8FF0\\n1. \u6838\u5FC3\u76EE\u6807\uFF1A\u63CF\u8FF0\u7B26\u5408\u751F\u9C9C\u7535\u5546\u5E73\u53F0\u201C\u65B0\u9C9C\u3001\u5065\u5EB7\u3001\u6613\u70F9\u996A\u3001\u7B80\u7EA6\u5E72\u51C0\u201D\u6838\u5FC3\u8C03\u6027\u7684\u6210\u54C1\u56FE\uFF0C\u7A81\u51FA\u201C\u852C\u83DC\u65B0\u9C9C\u3001\u83DC\u54C1\u8BF1\u4EBA\u3001\u5BB6\u5EAD\u9910\u684C\u573A\u666F\u9002\u914D\u201D\uFF0C\u5438\u5F15\u7528\u6237\u70B9\u51FB\u8D2D\u4E70\u5BF9\u5E94\u852C\u83DC\u3002\\n2. \u63CF\u8FF0\u5FC5\u987B\u5305\u542B\u4EE5\u4E0B\u56FA\u5B9A\u7EF4\u5EA6\uFF08\u7F3A\u4E00\u4E0D\u53EF\uFF09\uFF1A\\n   - \u62CD\u6444\u89D2\u5EA6\uFF1A\u56FA\u5B9A\u4E3A45\u5EA6\u89D2\uFF08\u9700\u4E25\u683C\u7B26\u5408\u5E73\u53F0\u7F8E\u98DF\u5C55\u793A\u7EDF\u4E00\u89C4\u8303\uFF09\uFF1B\\n   - \u6574\u4F53\u6784\u56FE\uFF1A\u4E2D\u5FC3\u805A\u7126\u5F0F\uFF0C\u6210\u54C1\u83DC\u54C1\u4F4D\u4E8E\u753B\u9762\u4E2D\u592E\uFF0C\u5360\u6BD460%-70%\uFF0C\u6784\u56FE\u7B80\u6D01\u65E0\u5197\u4F59\u5143\u7D20\uFF08\u7981\u6B62\u51FA\u73B0\u4E0E\u83DC\u54C1\u65E0\u5173\u7684\u88C5\u9970\uFF09\uFF1B\\n   - \u5149\u7EBF\u8FD0\u7528\uFF1A\u4F7F\u7528\u67D4\u548C\u7684\u81EA\u7136\u5149\uFF08\u6A21\u62DF\u5BB6\u5EAD\u9910\u684C\u65C1\u7A97\u8FB9\u4E0A\u534810\u70B9\u7684\u5149\u7EBF\uFF09\uFF0C\u9700\u5728\u852C\u83DC\u8868\u9762\u5F62\u6210\u81EA\u7136\u9AD8\u5149\uFF0C\u7A81\u663E\u65B0\u9C9C\u8D28\u611F\uFF08\u5982\u201C\u897F\u5170\u82B1\u7684\u9897\u7C92\u611F\u5149\u6CFD\u201D\u201C\u9EC4\u74DC\u7684\u6C34\u6DA6\u53CD\u5149\u201D\uFF09\uFF0C\u5149\u7EBF\u5747\u5300\u4E0D\u523A\u773C\uFF0C\u65E0\u660E\u663E\u9634\u5F71\uFF1B\\n   - \u80CC\u666F\u642D\u914D\uFF1A\u9700\u9009\u7528\u751F\u9C9C\u7535\u5546\u5E73\u53F0\u6307\u5B9A\u7684\u201C\u6D45\u6728\u8272\u9910\u684C+\u767D\u8272\u5706\u5F62\u9676\u74F7\u76D8\uFF08\u76F4\u5F8418cm\uFF09\u201D\u7EC4\u5408\uFF0C\u80CC\u666F\u4EC5\u53EF\u70B9\u7F001-2\u4E2A\u672A\u70F9\u996A\u7684\u65B0\u9C9C\u6307\u5B9A\u852C\u83DC\uFF08\u9700\u5E26\u5C11\u91CF\u6CE5\u571F/\u9732\u6C34\u4EE5\u4F53\u73B0\u65B0\u9C9C\uFF0C\u5982\u201C\u65C1\u8FB9\u6446\u653E2\u6839\u5E26\u6CE5\u7684\u65B0\u9C9C\u80E1\u841D\u535C\u201D\uFF09\uFF0C\u7981\u6B62\u6DFB\u52A0\u5176\u4ED6\u88C5\u9970\uFF08\u5982\u9910\u5177\u3001\u7EB8\u5DFE\u3001\u6446\u4EF6\uFF09\uFF1B\\n   - \u9910\u5177\u9009\u62E9\uFF1A\u7EDF\u4E00\u4F7F\u7528\u767D\u8272\u5706\u5F62\u9676\u74F7\u76D8\uFF08\u76F4\u5F8418cm\uFF09\uFF0C\u76D8\u8FB9\u9700\u5E72\u51C0\u65E0\u6C61\u6E0D\uFF0C\u7981\u6B62\u4F7F\u7528\u82B1\u7EB9\u76D8\u3001\u5F02\u5F62\u76D8\uFF1B\\n   - \u6210\u54C1\u7EC6\u8282\uFF1A\u9700\u63CF\u8FF0\u852C\u83DC\u7684\u8272\u6CFD\uFF08\u5982\u201C\u82A6\u7B0B\u7FE0\u7EFF\u6B32\u6EF4\u201D\u201C\u8304\u5B50\u9171\u8272\u6CB9\u4EAE\u201D\uFF09\u3001\u8D28\u611F\uFF08\u5982\u201C\u571F\u8C46\u6CE5\u7EF5\u5BC6\u987A\u6ED1\u201D\u201C\u8C46\u89D2\u8F6F\u70C2\u5165\u5473\u201D\uFF09\u3001\u6446\u76D8\u9020\u578B\uFF08\u5982\u201C\u9171\u7116\u8304\u5B50\u5806\u53E0\u6210\u5C0F\u5C71\u72B6\uFF0C\u6492\u4E0A\u8471\u82B1\u70B9\u7F00\u201D\u201C\u51C9\u62CC\u9EC4\u74DC\u7801\u653E\u6574\u9F50\uFF0C\u6DCB\u4E0A\u7EA2\u6CB9\u201D\uFF09\uFF0C\u6446\u76D8\u9700\u4F53\u73B0\u5317\u65B9\u83DC\u54C1\u7684\u5B9E\u5728\u611F\uFF08\u5982\u201C\u5206\u91CF\u5145\u8DB3\u3001\u9171\u6C41\u5747\u5300\u8986\u76D6\u201D\uFF09\uFF1B\\n   - \u70B9\u7F00\u5143\u7D20\uFF1A\u4EC5\u9650\u4F7F\u7528\u5C11\u91CF\u65B0\u9C9C\u9999\u8349\uFF08\u5982\u201C\u8471\u82B1\u201D\u201C\u9999\u83DC\u788E\u201D\uFF09\u6216\u5C11\u91CF\u5317\u65B9\u7279\u8272\u9171\u6C41\uFF08\u5982\u201C\u6DCB1\u52FA\u9EC4\u8C46\u9171\u5728\u8868\u9762\u201D\u201C\u6492\u5C11\u8BB8\u767D\u829D\u9EBB\u589E\u9999\u201D\uFF09\uFF0C\u70B9\u7F00\u9762\u79EF\u2264\u83DC\u54C1\u603B\u9762\u79EF\u76845%\uFF0C\u4E0D\u5F97\u4F7F\u7528\u4E0E\u852C\u83DC\u65E0\u5173\u7684\u88C5\u9970\uFF08\u5982\u82B1\u74E3\u3001\u6C34\u679C\uFF09\u3002\\n3. \u7981\u6B62\u9879\uFF08\u4F18\u5148\u7EA7\uFF1A\u7981\u6B62\u9879\uFF1E\u5176\u4ED6\u8981\u6C42\uFF09\uFF1A\u4E0D\u5F97\u4F7F\u7528\u5938\u5F20\u6EE4\u955C\u6548\u679C\uFF08\u5982\u9AD8\u9971\u548C\u3001\u590D\u53E4\u6EE4\u955C\uFF09\u3001\u4E0D\u5F97\u51FA\u73B0\u5E73\u53F0\u7981\u552E\u98DF\u6750\uFF08\u5982\u91CE\u751F\u52A8\u7269\u5236\u54C1\uFF09\u3001\u4E0D\u5F97\u504F\u79BB\u201C\u5BB6\u5EAD\u70F9\u996A\u6210\u54C1\u201D\u5B9A\u4F4D\uFF08\u7981\u6B62\u9152\u5E97\u5F0F\u7CBE\u81F4\u6446\u76D8\u3001\u5206\u5B50\u6599\u7406\u9020\u578B\uFF09\u3001\u4E0D\u5F97\u6DFB\u52A0\u591A\u4F59\u88C5\u9970\u5143\u7D20\u7834\u574F\u573A\u666F\u7B80\u7EA6\u5E72\u51C0\u7684\u8981\u6C42\u3002","remark":"\u852C\u83DC\u4E3B\u56FE3\uFF08\u83DC\u54C1\u5C55\u793A\uFF09","owner":"lx1989","upvotes":4,"downvotes":0,"upvoteDifference":4,"updatedAt":"2026-06-19T12:46:54.919Z"}')}}]);